class Task:
    def __init__(self, C, S, D, T):
        self.C = C
        self.S = S
        self.D = D
        self.T = T

def get_higher_priority_tasks(task_k_index, all_tasks):
    hp_k = []
    for i in range(task_k_index):
        hp_k.append(all_tasks[i])
    return hp_k

def check_hp_schedulability(task_set, k):
    for i in range(k - 1):
        if not is_task_schedulable(task_set[i], calculate_wcrt(task_set[i], task_set)):
            return False
    return True

def check_hp_strong_schedulability(task_set, k):
    for i in range(k - 1):
        if not (is_task_schedulable(task_set[i], calculate_wcrt(task_set[i], task_set)) and is_constrained_deadline(task_set[i])):
            return False
    return True

def categorize_tasks(hp_tasks, x_vector):
    T_0 = []
    T_1 = []
    for i, task_i in enumerate(hp_tasks):
        if x_vector[i] == 0:
            T_0.append(task_i)
        else:
            T_1.append(task_i)
    return T_0, T_1

def calculate_Q_x_i(task_i_index, k, S_values, x_vector):
    Q_x_i = 0
    for j in range(task_i_index, k - 1):
        Q_x_i += S_values[j] * x_vector[j]
    return Q_x_i

def calculate_blocking_time(task_k, hp_tasks):
    B_k = task_k.S
    for hp_task_i in hp_tasks:
        B_k += min(hp_task_i.C, hp_task_i.S)
    return B_k

def check_suspension_oblivious_schedulability(task_k, hp_tasks):
    for t in range(1, task_k.D + 1):
        workload = task_k.C + task_k.S
        for hp_task_i in hp_tasks:
            workload += math.floor(t / hp_task_i.T) * (hp_task_i.C + hp_task_i.S)
        if workload <= t:
            return True
    return False

def check_jitter_schedulability(task_k, hp_tasks, hp_R_values):
    for t in range(1, task_k.D + 1):
        workload = task_k.C + task_k.S
        for i, hp_task_i in enumerate(hp_tasks):
            jitter_i = hp_R_values[i] - hp_task_i.C
            workload += math.floor((t + jitter_i) / hp_task_i.T) * hp_task_i.C
        if workload <= t:
            return True
    return False

def check_blocking_schedulability(task_k, hp_tasks, B_k):
    for t in range(1, task_k.D + 1):
        workload = task_k.C + B_k
        for hp_task_i in hp_tasks:
            workload += math.floor(t / hp_task_i.T) * hp_task_i.C
        if workload <= t:
            return True
    return False

def remove_job_safe(task_i, job_to_remove):
    if task_i.R <= task_i.T:
        # No other jobs of task_i are affected
        return True
    else:
        # May affect other jobs if R_i > T_i (carry-in)
        return False

def bound_total_idle_time(t_1, t, t_points, x_vector, S_values, sigma_values):
    total_idle = 0
    for j in range(len(t_points) - 1):
        if t_points[j] < t:
            interval_end = min(t_points[j+1], t)
            # This is a simplification, actual sigma_j is for [t_j, t_j+1)
            # The corollary sums up to 'i' where t_i < t <= t_i+1
            if j < i_where_t_falls:
                total_idle += x_vector[j] * sigma_values[j] # or S_values[j]
    return total_idle

def get_exec_k_bound(t_k, t, f_k, C_k):
    if t_k <= t < f_k:
        return 'less than C_k'
    else:
        return 'not applicable'

def get_exec_bound_T1(task_j, delta):
    # Assumes task_j is in T_1 and no residual workload at start of delta
    return W_1_j(delta, task_j.T, task_j.C)

def W_0_j(delta, c_star_j, T_j, R_j, C_j):
    if c_star_j == 0:
        return W_1_j(delta, T_j, C_j)
    else:
        rho_j = T_j - R_j + c_star_j
        if delta <= c_star_j:
            return delta
        elif delta <= rho_j:
            return c_star_j
        else:
            return c_star_j + W_1_j(delta - rho_j, T_j, C_j)

def get_exec_bound_T0(task_j, delta, c_star_j):
    # Assumes task_j is in T_0 and has residual workload c_star_j at start of delta
    return W_0_j(delta, c_star_j, task_j.T, task_j.R, task_j.C)

def check_workload_inequality(t, t_1, t_points, C_k, x_vector, W_1_funcs, W_0_funcs, sigma_values):
    lhs = 0
    # For Eq. (10) (i.e., for t < t_k)
    if t < t_points[k-1]: # t_k is t_points[k-1]
        for j in range(get_index_for_t(t, t_points) + 1):
            if x_vector[j] == 1:
                lhs += W_1_funcs[j](t - t_points[j]) + sigma_values[j]
            else:
                lhs += W_0_funcs[j](t - t_points[j])
        return lhs >= t - t_1
    # For Eq. (11) (i.e., for t_k <= t < f_k)
    else:
        lhs = C_k
        for j in range(k - 1):
            if x_vector[j] == 1:
                lhs += W_1_funcs[j](t - t_points[j]) + sigma_values[j]
            else:
                lhs += W_0_funcs[j](t - t_points[j])
        return lhs > t - t_1

def bound_W_1_j(delta, T_j, C_j):
    return math.floor(delta / T_j) * C_j

def bound_W_0_j(delta, T_j, R_j, C_j):
    return math.floor((delta + R_j - C_j) / T_j) * C_j

def calculate_t_star_i(i, t_1, x_vector, sigma_values):
    if i == 1:
        return t_1
    else:
        t_star_prev = calculate_t_star_i(i - 1, t_1, x_vector, sigma_values)
        return t_star_prev + x_vector[i-2] * sigma_values[i-2] # x_vector and sigma_values are 0-indexed

def check_workload_inequality_t_star(t, t_star_k, f_k, C_k, x_vector, W_1_funcs, W_0_funcs, t_star_points):
    if t_star_k <= t < f_k:
        lhs = C_k
        for j in range(k - 1):
            if x_vector[j] == 1:
                lhs += W_1_funcs[j](t - t_star_points[j])
            else:
                lhs += W_0_funcs[j](t - t_star_points[j])
        return lhs > t - t_star_k
    return False

def calculate_X_j(task_j_index, k, x_vector, sigma_values):
    X_j = 0
    for l in range(task_j_index, k - 1):
        X_j += x_vector[l] * sigma_values[l]
    return X_j

def check_response_time_lower_bound(theta, C_k, hp_tasks, X_values, x_vector, R_values):
    lhs = C_k
    for j in range(len(hp_tasks)):
        hp_task_j = hp_tasks[j]
        if x_vector[j] == 1:
            lhs += math.floor((theta + X_values[j]) / hp_task_j.T) * hp_task_j.C
        else:
            lhs += math.floor((theta + X_values[j] + (R_values[j] - hp_task_j.C)) / hp_task_j.T) * hp_task_j.C
    return lhs > theta

def calculate_R_k_upper_bound(task_k, hp_tasks, x_vector, hp_R_values):
    t_current = task_k.C + task_k.S
    while True:
        t_next = task_k.C + task_k.S
        for i, hp_task_i in enumerate(hp_tasks):
            Q_x_i = calculate_Q_x_i(i, len(hp_tasks) + 1, [t.S for t in hp_tasks], x_vector)
            term = t_current + Q_x_i + (1 - x_vector[i]) * (hp_R_values[i] - hp_task_i.C)
            t_next += math.floor(term / hp_task_i.T) * hp_task_i.C
        if t_next == t_current:
            return t_next
        if t_next > task_k.D: # Or some other upper bound like T_k
            return float('inf') # Not schedulable within D_k
        t_current = t_next

def check_unifying_schedulability(task_k, hp_tasks, hp_R_values):
    # Ensure hp_R_values are <= hp_tasks.T
    for i in range(len(hp_tasks)):
        if hp_R_values[i] > hp_tasks[i].T:
            # This case is not covered by the corollary's assumption
            return False # Or handle appropriately

    # Iterate through all 2^(k-1) x vectors
    num_hp_tasks = len(hp_tasks)
    for i in range(2**num_hp_tasks):
        x_vector = [(i >> j) & 1 for j in range(num_hp_tasks)] # Generate binary vector

        R_k_x = calculate_R_k_upper_bound(task_k, hp_tasks, x_vector, hp_R_values)
        if R_k_x <= task_k.D:
            return True
    return False
